    String endpoint = RegionUtils.getRegion(accessPointRegionKey)
        .getServiceEndpoint("s3");

    // The SDK 1.12.x resolves access point endpoints as "s3.accesspoint-<region>"
    // instead of the expected "s3-accesspoint.<region>". Once that is fixed
    // upstream this replacement becomes a no-op.
    return endpoint.replace("s3.accesspoint-", "s3-accesspoint.");
  }'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF
