  public void testWriteWrapsSQLException() throws Exception {
    PreparedStatement statement = mock(PreparedStatement.class);
    doThrow(new SQLException("addBatch failed")).when(statement).addBatch();

    DBWritable key = mock(DBWritable.class);
    DBOutputFormat<DBWritable, NullWritable>.DBRecordWriter writer =
        format.new DBRecordWriter(mock(Connection.class), statement);

    IOException ioe = LambdaTestUtils.intercept(IOException.class,
        "Failed to execute SQL statement for key ",
        () -> writer.write(key, NullWritable.get()));
    assertTrue("Original SQLException should be the cause",
        ioe.getCause() instanceof SQLException);
  }

}

